                             UNION ALL
                            SELECT * FROM CKTS_LC_SHYDDCL_SHXT WHERE SBYWB_DM='A0301001') T;
  OPEN BJTS_CURSOR_029;
  BJTS_CURSOR_LOOP_029: LOOP
    SET BJTS_CURSOR_DONE_029 = FALSE;
